// One plain-text e-mail with the new posts, grouped by company. No new posts: no e-mail.
const cfg = $('Configure').first().json;
const posts = $input.all().map(i => i.json).filter(p => p.id && p.url);
if (!posts.length) return [];
const byCompany = {};
for (const p of posts) (byCompany[p.company || 'Unknown'] ||= []).push(p);
const blocks = Object.entries(byCompany).map(([company, list]) => {
  list.sort((a, b) => (b.postedAt || '').localeCompare(a.postedAt || ''));
  const lines = list.map(p => {
    const text = (p.text || '').replace(/\s+/g, ' ').slice(0, 280);
    const by = p.isRepost && p.author ? ` (repost from ${p.author})` : '';
    return `- ${(p.postedAt || '').slice(0, 10)}${by}: ${text}\n  ${p.reactions ?? 0} reactions, ${p.comments ?? 0} comments · ${p.url}`;
  });
  return `${company} (${list.length})\n${lines.join('\n')}`;
});
return [{ json: {
  sendTo: cfg.sendTo,
  subject: `${posts.length} new LinkedIn post${posts.length > 1 ? 's' : ''} from ${Object.keys(byCompany).length} compan${Object.keys(byCompany).length > 1 ? 'ies' : 'y'}`,
  text: blocks.join('\n\n'),
} }];
